/* ================================================================
   SalasACotizacion.js  -  Puente "Salas -> Cotizador"
   Generado automaticamente desde la planilla de precios de salas
   (precio de venta con IVA incluido) y las fotos del Stock.
   ================================================================ */
(function(){
  "use strict";
  window.SALAS_PRECIOS_URL = window.SALAS_PRECIOS_URL || "";

  window.SALAS_refrescarPrecios = async function(){
    if(!window.SALAS_PRECIOS_URL) return 0;
    try{
      const r = await fetch(window.SALAS_PRECIOS_URL, {cache:"no-store"});
      const data = await r.json();
      const mapa = (data && data.precios) ? data.precios : data;
      let n = 0;
      Object.keys(mapa||{}).forEach(function(sku){
        const val = parseInt(mapa[sku],10);
        if(window.SALAS_CATALOGO[sku] && val>0){ window.SALAS_CATALOGO[sku].p = val; n++; }
      });
      document.querySelectorAll("[data-sku]").forEach(function(el){
        const sku = el.getAttribute("data-sku");
        if(mapa[sku] && parseInt(mapa[sku],10)>0){ el.setAttribute("data-precio", String(parseInt(mapa[sku],10))); }
      });
      if(n) console.log("[Salas] Precios refrescados en vivo:", n);
      return n;
    }catch(e){ console.warn("[Salas] No se pudo refrescar precios en vivo; uso los guardados.", e); return 0; }
  };

  function absImg(img){
    if(!img) return "";
    if(/^https?:|^data:/.test(img)) return img;
    try { return new URL(img, location.href).href; } catch(e){ return img; }
  }

  window.SALAS_enviarACotizacion = function(items, extra){
    extra = extra || {};
    const productos = (items||[]).map(function(it){
      const c = window.SALAS_CATALOGO[it.sku] || {};
      const precio = (it.precio!=null && it.precio!=="") ? it.precio : (c.p||0);
      const nombre = it.nombre || c.n || it.sku;
      const img = it.img || c.img || "";
      return { nombre:nombre, desc:"", cant:String(it.cant||1), precio:String(precio), modo:"iva", zoom:100, img:absImg(img) };
    }).filter(function(p){ return p.nombre; });
    if(!productos.length){ alert("No hay productos seleccionados."); return false; }
    const payload = { _origen:"salas", productos:productos };
    if(extra.sala) payload.sala = extra.sala;
    if(extra.cliente) payload.cliente = extra.cliente;
    try{ localStorage.setItem("oc_sala_pendiente", JSON.stringify(payload)); }
    catch(e){ alert("No se pudo preparar la cotizacion (memoria del navegador llena)."); return false; }
    window.open("CotizadorOpenCluster.html", "_blank");
    return true;
  };
})();
